<?php

declare(strict_types=1);

namespace App\Tools\TaxReformSimulator\Presentation\Controllers; use App\Core\Access\Services\ToolFeatureRequestAuthorizer; use App\Http\Controllers\Controller; use App\Tools\TaxReformSimulator\Tool; use App\Tools\TaxReformSimulator\Application\Actions\{CalculateTool,ShowToolPage}; use App\Tools\TaxReformSimulator\Application\Data\CalculationInput; use App\Tools\TaxReformSimulator\Presentation\Requests\ExecuteToolRequest; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; final class ToolController extends Controller { public function index(Request $request,ShowToolPage $page):View{return view('tools-simulador-reforma-tributaria-consumo::index',$page->execute());} public function calculate(ExecuteToolRequest $request,CalculateTool $action,ShowToolPage $page,ToolFeatureRequestAuthorizer $features,Tool $module):View{$d=$request->validated();$diag=(bool)($d['show_diagnostics']??false);$features->requireIf($diag,$module,'transition_diagnostics',$request);$r=$action->execute(new CalculationInput($d['revenue'],$d['legacy_federal_rate'],$d['legacy_subnational_rate'],$d['cbs_reference_rate'],$d['ibs_reference_rate'],$d['credit_base_percent'],(int)$d['year']));$request->flash();return view('tools-simulador-reforma-tributaria-consumo::index',[...$page->execute(),'result'=>$r,'showDiagnostics'=>$diag]);} }
